import {encodeWav} from './stems.js';
const $=s=>document.querySelector(s),sleep=ms=>new Promise(r=>setTimeout(r,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(n=>n.toString(16).padStart(2,'0')).join('');
const files=['app.js','panels.js','styles.css','stems.js','stem-crate.js','engine.js','local-audio-library.js','stem-crate-harness.js'];
const identities=async()=>Object.fromEntries(await Promise.all(files.map(async f=>[f,await hash(await(await fetch(f,{cache:'no-store'})).arrayBuffer())])));
async function until(fn,label,ms=120000){const end=performance.now()+ms;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(20);}}
const click=s=>{assert($(s),'Missing '+s);$(s).click();},button=(i,a)=>`[data-deck="${i}"][data-action="${a}"]`;
const KEY='openplay-stem-crate-workflow';let app,report;
const save=()=>{sessionStorage.setItem(KEY,JSON.stringify(report));$('#crate-original').textContent=JSON.stringify(report,null,2);$('#crate-results').textContent=JSON.stringify({...report,recording:report.recording?{...report.recording,base64:'Retained in original report'}:null},null,2);};
function base64(b){let s='';for(let n=0;n<b.length;n+=16384)s+=String.fromCharCode(...b.subarray(n,n+16384));return btoa(s);}
function measure(a,sr,from,to){const first=Math.ceil(from*sr),last=Math.floor(to*sr),cross=[];let sum=0;assert(first>=0&&last<=a.length&&last>first,'Invalid fixed window');for(let n=first;n<last;n++){sum+=a[n]**2;if(n>first&&a[n-1]<0&&a[n]>=0)cross.push((n-1-a[n-1]/(a[n]-a[n-1]))/sr);}return{rms:Math.sqrt(sum/(last-first)),hz:cross.length>3?(cross.length-1)/(cross.at(-1)-cross[0]):null};}
const statusNode=track=>$(`[data-stem-cache-status="${track.id}"]`);
async function importFixture(){
 const {engine,state}=app;await engine.resume();engine.audioMonitor.mutePhysical(true);await until(()=>engine.audioMonitor.snapshot().physicalMuted,'Physical mute');
 const sr=44100,b=engine.ctx.createBuffer(2,sr*8,sr);for(let c=0;c<2;c++){const a=b.getChannelData(c);for(let n=0;n<a.length;n++)a[n]=.12*Math.sin(2*Math.PI*(c?880:660)*n/sr);}
 const bytes=encodeWav(b),digest=await hash(bytes),transfer=new DataTransfer();transfer.items.add(new File([bytes],'stem-crate-check.wav',{type:'audio/wav'}));const input=$('#audio-files');input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}));
 await until(()=>state.tracks.some(t=>t.contentHash===digest&&t.storage==='saved'),'Actual file import and IndexedDB save');report={startedAt:new Date().toISOString(),phase:0,completed:false,scope:'Actual production File input change (synthetic chooser selection), crate drop, pinned SCNet, two reloads, cached decode, real keyboard removal, OS Trash, original library/File preservation and browser audio. Not native picker/desktop16/controller/model-quality/full reference acceptance.',criteria:{frequencyErrorHz:1,minimumRMS:.005},trackId:'local-'+digest,originalFileSHA256:digest,sourceBefore:await identities(),errors:[],checks:[]};save();$('#crate-prepare').disabled=false;$('#crate-status').textContent='Owned test file imported; run crate preparation';
}
async function prepareCrate(){
 const {state,engine}=app;$('#crate-prepare').disabled=true;try{
  const track=state.tracks.find(t=>t.id===report.trackId);assert(track&&state.decks.every(d=>d.track!==track),'Fixture must not be loaded before crate preparation');
  const dt=new DataTransfer();dt.setData('text/plain',track.id);$('[data-crate="stems"]').dispatchEvent(new DragEvent('drop',{dataTransfer:dt,bubbles:true,cancelable:true}));click('[data-crate="stems"]');
  await until(()=>track.inStemCrate&&statusNode(track),'Crate membership');report.pending={member:track.inStemCrate,label:statusNode(track).getAttribute('aria-label'),loadedOnDeck:state.decks.some(d=>d.track===track)};assert(!report.pending.loadedOnDeck&&report.pending.label==='Stems preparing','Pending crate must be visible/grey without deck load');
  await until(()=>track.stemJob&&statusNode(track)?.classList.contains('stem-ready'),'Actual prepared readiness');report.job=track.stemJob;report.initialAPI=await(await fetch('/api/stems/'+report.job)).json();assert(report.initialAPI.state==='complete'&&report.initialAPI.model==='SCNet-large official','Real SCNet preparation required');report.originalLibraryKept=state.tracks.includes(track);report.phase=1;report.checks.push('Drop adds/persists membership and prepares via SCNet while track is not loaded; pending and verified ready states observed');save();$('#crate-status').textContent='Phase1 passed; reload to check saved crate before decoding';$('#crate-reload').hidden=false;
 }catch(e){fail(e);}
}
async function checkReload(){
 const {state,engine}=app,track=state.tracks.find(t=>t.id===report.trackId);assert(track&&track.inStemCrate&&track.stemJob===report.job,'Saved crate membership/association not restored');assert(!engine.stemBuffers.has(track.id),'Readiness must not require decoded Stems');click('[data-crate="stems"]');await until(()=>statusNode(track)?.classList.contains('stem-ready'),'Saved readiness');
 const original=await track.readFile();assert(await hash(await original.arrayBuffer())===report.originalFileSHA256,'Stored original File changed');report.reloaded={member:track.inStemCrate,readyLabel:statusNode(track).getAttribute('aria-label'),decodedStems:engine.stemBuffers.has(track.id),savedFileHashMatches:true};report.checks.push('First reload restores original File and crate; live service verifies readiness without decoding or inferring');save();$('#crate-play').disabled=false;$('#crate-status').textContent='Saved crate verified; start loaded playback/removal check';
}
async function playAndRemove(){
 const {state,engine}=app,track=state.tracks.find(t=>t.id===report.trackId);$('#crate-play').disabled=true;
 try{
  await engine.resume();engine.audioMonitor.mutePhysical(true);await until(()=>engine.audioMonitor.snapshot().physicalMuted,'Physical mute');for(const d of state.decks)engine.pause(d);
  const row=$(`[data-track="${track.id}"]`);row.click();row.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowLeft',code:'ArrowLeft',shiftKey:true,bubbles:true,cancelable:true}));await until(()=>state.decks[0].track===track&&!state.decks[0].processing,'Load restored original');const d=state.decks[0];
  click(button(0,'tab')+'[data-tab="Stems"]');click(button(0,'stemPrepare'));click('#stems-queue');await until(()=>engine.stemBuffers.has(track.id)&&!$('#stems-queue').disabled,'Decode saved preparation');assert(track.stemJob===report.job,'Cache decode unexpectedly chose a new job');click('#modal-close');
  if(!d.loop)click(button(0,'loop'));click(button(0,'play'));await until(()=>d.playing&&!d.processing,'Loop playback');await engine.recordStart();report.recordStart=engine.recordStarted;report.windows=[];
  const sample=async name=>{const at=engine.ctx.currentTime;report.windows.push({name,from:at-engine.recordStarted+.15,to:at-engine.recordStarted+.45});await until(()=>engine.ctx.currentTime>=at+.5,'Declared audio window',10000);};await sample('before-remove');const voice=engine.voices.get(0),buffers=engine.stemBuffers.get(track.id);click('[data-crate="stems"]');const selected=$(`[data-track="${track.id}"]`);selected.click();selected.focus();$('#crate-status').textContent='READY FOR COMMAND+DELETE: track row focused; generated loop is playing';
  await until(()=>!track.inStemCrate,'Real library keyboard removal');report.removal={member:track.inStemCrate,savedJob:track.stemJob??null,libraryTrackKept:state.tracks.includes(track),sameVoice:engine.voices.get(0)===voice,sameBuffers:engine.stemBuffers.get(track.id)===buffers,playing:d.playing,absentFromCrate:!$(`[data-track="${track.id}"]`),message:track.stemState};assert(report.removal.libraryTrackKept&&report.removal.sameVoice&&report.removal.sameBuffers&&d.playing&&report.removal.absentFromCrate&&!track.stemJob,'Crate removal changed library or loaded audio');await sample('after-remove');click('[data-crate="all"]');assert($(`[data-track="${track.id}"]`),'Original missing from All music');const kept=await track.readFile();assert(await hash(await kept.arrayBuffer())===report.originalFileSHA256,'Original File was removed or changed');report.phase=2;report.checks.push('Real Command+Delete removes prepared membership/files while the original library File, playing voice and decoded Stems stay intact');
 }catch(e){report.errors.push({message:e.message,stack:e.stack});}
 finally{
  for(const d of state.decks)engine.pause(d);if(engine.recording){const blob=await engine.recordStop(),bytes=new Uint8Array(await blob.arrayBuffer());report.recording={bytes:bytes.length,format:blob.type,sha256:await hash(bytes),base64:base64(bytes)};try{const b=await engine.ctx.decodeAudioData(bytes.buffer.slice(0));report.decoded={duration:b.duration,frames:b.length,sampleRate:b.sampleRate,channels:b.numberOfChannels};assert(b.numberOfChannels===2,'Stereo master');for(let c=0;c<2;c++)for(const v of b.getChannelData(c))assert(Number.isFinite(v),'Nonfinite recording');report.audio=report.windows.map(w=>({...w,channels:[0,1].map(c=>measure(b.getChannelData(c),b.sampleRate,w.from,w.to))}));assert(report.audio.length===2,'Both fixed windows required');for(const w of report.audio)for(let c=0;c<2;c++)assert(w.channels[c].rms>.005&&Math.abs(w.channels[c].hz-(c?880:660))<1,w.name+' audio carrier');report.checks.push('Whole finite master and before/after removal tone windows meet fixed pitch/RMS criteria');}catch(e){report.errors.push({message:e.message,stack:e.stack});}}
  save();$('#crate-status').textContent=report.errors.length?'Failed: '+report.errors.map(e=>e.message).join('; '):'Phase2 passed; reload to verify removal persists';$('#crate-reload').hidden=!!report.errors.length;
 }
}
async function finalReload(){
 const {state,engine}=app,track=state.tracks.find(t=>t.id===report.trackId);assert(track&&!track.inStemCrate&&!track.stemJob,'Removed membership resurrected');click('[data-crate="stems"]');assert(!$(`[data-track="${track.id}"]`),'Removed entry reappeared');click('[data-crate="all"]');assert($(`[data-track="${track.id}"]`),'Original library track missing after second reload');assert(await hash(await(await track.readFile()).arrayBuffer())===report.originalFileSHA256,'Original File changed after removal/reload');report.finalReload={member:false,originalFileAndLibraryRetained:true,decodedStems:engine.stemBuffers.has(track.id)};report.checks.push('Second reload keeps crate removal and original File/library entry');report.sourceAfter=await identities();report.sourceStable=JSON.stringify(report.sourceBefore)===JSON.stringify(report.sourceAfter);report.completed=report.checks.length===5&&!report.errors.length&&report.sourceStable;report.finishedAt=new Date().toISOString();save();$('#crate-original').textContent=JSON.stringify(report,null,2);$('#crate-status').textContent=report.completed?'Scoped persistent Stems crate workflow passed; decks stopped':'Failed final ownership/source check';const a=$('#crate-download');a.href=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));a.download='stem-crate-original.json';a.hidden=false;
}
function fail(e){if(report){report.errors.push({message:e.message,stack:e.stack});save();}$('#crate-status').textContent='Failed: '+e.message;}
$('#crate-import').onclick=()=>importFixture().catch(fail);$('#crate-prepare').onclick=prepareCrate;$('#crate-play').onclick=playAndRemove;$('#crate-reload').onclick=()=>location.reload();
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[1].track,'Actual app');app=window.openPlay;await until(()=>!app.state.analysis,'Initial analysis');const saved=sessionStorage.getItem(KEY);if(saved){report=JSON.parse(saved);if(!report.errors.length&&report.phase===1){await checkReload();return;}if(!report.errors.length&&report.phase===2){await finalReload();return;}}$('#crate-import').disabled=false;$('#crate-status').textContent='Import owned WAV through production file input';}
